'use server'

import { cookies } from 'next/headers'
import { revalidatePath } from 'next/cache'

/**
 * The notification preference is persisted in a cookie so it survives across
 * requests without a database. The Server Action flips it and then asks Next.js
 * to refresh the data for the current route.
 */
const PREF_COOKIE = 'notify-pref'

export async function getNotificationPreference(): Promise<boolean> {
  const store = await cookies()
  return store.get(PREF_COOKIE)?.value === 'on'
}

export async function toggleNotificationPreference(): Promise<void> {
  const store = await cookies()
  const current = store.get(PREF_COOKIE)?.value === 'on'
  const next = !current

  store.set(PREF_COOKIE, next ? 'on' : 'off', {
    httpOnly: true,
    sameSite: 'lax',
    path: '/',
  })

  // Next.js' recommended way to refresh the *current* page from within a Server
  // Action without redirecting: purge the router cache for this route so the
  // page re-renders with the updated data on the following request. We do NOT
  // call redirect() here, which would navigate away from the current page.
  revalidatePath('/')
}

