import {
  getNotificationPreference,
  toggleNotificationPreference,
} from './actions'

export default async function Home() {
  const enabled = await getNotificationPreference()

  return (
    <main>
      <h1>Settings</h1>
      <p>Notification preference</p>

      {/* The form is the recommended way to invoke a Server Action. */}
      <form action={toggleNotificationPreference}>
        <p>
          Status:{' '}
          <strong aria-live="polite">{enabled ? 'On' : 'Off'}</strong>
        </p>
        <button type="submit">
          Turn notifications {enabled ? 'off' : 'on'}
        </button>
      </form>
    </main>
  )
}

